{
	int total = 0, bad = 0;

	bad += check_errors(&total);
	bad += check_dec(DEC4_CASES, (int)(sizeof(DEC4_CASES) / sizeof(DEC4_CASES[0])), &total);
	bad += check_rel("quad_solve", QUAD_SOLVE, (int)(sizeof(QUAD_SOLVE) / sizeof(QUAD_SOLVE[0])), 3, &total);
	bad += check_rel("deriv_poly3", DERIV_POLY3, (int)(sizeof(DERIV_POLY3) / sizeof(DERIV_POLY3[0])), 5, &total);
	bad += check_rel("integr_poly3", INTEGR_POLY3, (int)(sizeof(INTEGR_POLY3) / sizeof(INTEGR_POLY3[0])), 6, &total);
	bad += check_rel("linear2", LINEAR2, (int)(sizeof(LINEAR2) / sizeof(LINEAR2[0])), 6, &total);
	bad += check_rel("exp_solve", EXP_SOLVE, (int)(sizeof(EXP_SOLVE) / sizeof(EXP_SOLVE[0])), 2, &total);
	bad += check_rel("kinematic_v", KINEMATIC_V, (int)(sizeof(KINEMATIC_V) / sizeof(KINEMATIC_V[0])), 3, &total);
	bad += check_rel("proj_range", PROJ_RANGE, (int)(sizeof(PROJ_RANGE) / sizeof(PROJ_RANGE[0])), 3, &total);
	bad += check_rel("ohm_i", OHM_I, (int)(sizeof(OHM_I) / sizeof(OHM_I[0])), 2, &total);
	bad += check_rel("moles", MOLES, (int)(sizeof(MOLES) / sizeof(MOLES[0])), 2, &total);
	bad += check_rel("dilution", DILUTION, (int)(sizeof(DILUTION) / sizeof(DILUTION[0])), 3, &total);
	bad += check_rel("gas_p", GAS_P, (int)(sizeof(GAS_P) / sizeof(GAS_P[0])), 3, &total);
	bad += check_rel("sin_eval", SIN_EVAL, (int)(sizeof(SIN_EVAL) / sizeof(SIN_EVAL[0])), 1, &total);
	bad += check_rel("cos_eval", COS_EVAL, (int)(sizeof(COS_EVAL) / sizeof(COS_EVAL[0])), 1, &total);
	bad += check_rel("tan_eval", TAN_EVAL, (int)(sizeof(TAN_EVAL) / sizeof(TAN_EVAL[0])), 1, &total);
	bad += check_rel("pythagoras", PYTHAGORAS, (int)(sizeof(PYTHAGORAS) / sizeof(PYTHAGORAS[0])), 2, &total);
	bad += check_rel("law_sines", LAW_SINES, (int)(sizeof(LAW_SINES) / sizeof(LAW_SINES[0])), 3, &total);
	bad += check_rel("law_cosines", LAW_COSINES, (int)(sizeof(LAW_COSINES) / sizeof(LAW_COSINES[0])), 3, &total);
	bad += check_rel("arc_length", ARC_LENGTH, (int)(sizeof(ARC_LENGTH) / sizeof(ARC_LENGTH[0])), 2, &total);
	bad += check_rel("log_eval", LOG_EVAL, (int)(sizeof(LOG_EVAL) / sizeof(LOG_EVAL[0])), 2, &total);
	bad += check_rel("ln_eval", LN_EVAL, (int)(sizeof(LN_EVAL) / sizeof(LN_EVAL[0])), 1, &total);
	bad += check_rel("log10_eval", LOG10_EVAL, (int)(sizeof(LOG10_EVAL) / sizeof(LOG10_EVAL[0])), 1, &total);
	bad += check_rel("compound_interest", COMPOUND_INTEREST, (int)(sizeof(COMPOUND_INTEREST) / sizeof(COMPOUND_INTEREST[0])), 4, &total);
	bad += check_rel("continuous_growth", CONTINUOUS_GROWTH, (int)(sizeof(CONTINUOUS_GROWTH) / sizeof(CONTINUOUS_GROWTH[0])), 3, &total);
	bad += check_rel("half_life", HALF_LIFE, (int)(sizeof(HALF_LIFE) / sizeof(HALF_LIFE[0])), 3, &total);
	bad += check_rel("doubling_time", DOUBLING_TIME, (int)(sizeof(DOUBLING_TIME) / sizeof(DOUBLING_TIME[0])), 1, &total);
	bad += check_rel("arith_seq", ARITH_SEQ, (int)(sizeof(ARITH_SEQ) / sizeof(ARITH_SEQ[0])), 3, &total);
	bad += check_rel("geom_seq", GEOM_SEQ, (int)(sizeof(GEOM_SEQ) / sizeof(GEOM_SEQ[0])), 3, &total);
	bad += check_rel("abs_value_eq", ABS_VALUE_EQ, (int)(sizeof(ABS_VALUE_EQ) / sizeof(ABS_VALUE_EQ[0])), 3, &total);
	bad += check_rel("linear_ineq", LINEAR_INEQ, (int)(sizeof(LINEAR_INEQ) / sizeof(LINEAR_INEQ[0])), 3, &total);
	bad += check_rel("system2", SYSTEM2, (int)(sizeof(SYSTEM2) / sizeof(SYSTEM2[0])), 6, &total);
	bad += check_rel("complete_square", COMPLETE_SQUARE, (int)(sizeof(COMPLETE_SQUARE) / sizeof(COMPLETE_SQUARE[0])), 3, &total);
	bad += check_rel("factor_quadratic", FACTOR_QUADRATIC, (int)(sizeof(FACTOR_QUADRATIC) / sizeof(FACTOR_QUADRATIC[0])), 3, &total);
	printf("TOTAL: %d assertions, %d mismatches -> %s\n", total, bad,
	       bad == 0 ? "PASS" : "FAIL");
	return bad == 0 ? 0 : 1;
}
